CREATE TEMP TABLE etl_recon ON COMMIT DROP AS
SELECT now()                                                  AS started_at,
       (SELECT COUNT(*) FROM orders WHERE status = 'COMPLETED') AS source_order_count,
       (SELECT COALESCE(SUM(order_count), 0)
          FROM dash_revenue_by_category)                      AS loaded_order_count;

ALTER TABLE etl_recon ADD COLUMN mismatch bigint;
UPDATE etl_recon SET mismatch = source_order_count - loaded_order_count;

INSERT INTO etl_run_log (started_at, finished_at, source_order_count, loaded_order_count, mismatch)
SELECT started_at, clock_timestamp(), source_order_count, loaded_order_count, mismatch
FROM   etl_recon;

-- Abort (and roll back the whole run) unless the order counts reconcile exactly.
DO $$
DECLARE
    r etl_recon%ROWTYPE;
BEGIN
    SELECT * INTO r FROM etl_recon;
    IF r.mismatch <> 0 THEN
        RAISE EXCEPTION 'ETL reconciliation failed: source_order_count=% loaded_order_count=% mismatch=%',
            r.source_order_count, r.loaded_order_count, r.mismatch;
    END IF;
END
$$;

